1	/**
2	 * Lark Interactive Card (Schema 2.0) Builder
3	 *
4	 * Transforms standard Markdown text into Feishu Interactive Card Schema 2.0 JSON.
5	 * Features:
6	 * - Markdown dialect optimization (heading demotion, code block protection, table spacing)
7	 * - Strip invalid non-img_ image keys from markdown elements (CardKit 200570 protection)
8	 * - Section length management & code-fence safe truncation
9	 * - UTF-8 byte budget management (<= 24KB card JSON)
10	 * - Image extraction and upload via Lark image API with graceful text fallback
11	 * - Nonce-protected code placeholders preventing user text collision
12	 */
13	
14	import crypto from "node:crypto";
15	
16	export const CARD_MAX_BYTES = 24 * 1024; // 24KB (留 20% 余量应对飞书 30KB 硬限)
17	export const SECTION_SOFT_LIMIT = 2000;
18	export const SECTION_HARD_LIMIT = 4000;
19	export const MAX_SECTIONS = 4;
20	export const EMPTY_TEXT_FALLBACK = "（Agent 未返回文本）";
21	
22	export type FeishuCardV2 = {
23	  schema: "2.0";
24	  config: {
25	    update_multi: boolean;
26	    enable_forward?: boolean;
27	    width_mode?: string;
28	    summary?: { content: string };
29	    [key: string]: unknown;
30	  };
31	  header?: {
32	    title: { tag: "plain_text" | "lark_md"; content: string };
33	    subtitle?: { tag: "plain_text"; content: string };
34	    template?: string;
35	    [key: string]: unknown;
36	  };
37	  body: {
38	    direction: "vertical";
39	    vertical_spacing: "medium" | "small" | "large";
40	    elements: Array<Record<string, unknown>>;
41	  };
42	};
43	
44	/**
45	 * BodySection (m4: 已清理无消费方的 expanded 字段，Schema 2.0 平铺渲染)
46	 */
47	export interface BodySection {
48	  text: string;
49	}
50	
51	export interface LarkCardOptions {
52	  title?: string;
53	  subtitle?: string;
54	  template?: string;
55	  status?: "done" | "warning" | "error" | "running";
56	  sessionUrl?: string;
57	  summary?: string;
58	  uploadImage?: (src: string) => Promise<string>;
59	}
60	
61	export interface MarkdownFence {
62	  marker: string;
63	  opener: string;
64	}
65	
66	/**
67	 * Tracks markdown code fences line by line.
68	 * Supports both ``` and ~~~ fences of length 3+.
69	 *
70	 * m8: 单行内同时开闭（如 ``` inline ```）不当跨行开围栏处理。
71	 */
72	export function nextMarkdownFence(
73	  line: string,
74	  current: MarkdownFence | null,
75	): MarkdownFence | null {
76	  const trimmed = line.trim();
77	  if (!current) {
78	    const opener = trimmed.match(/^(`{3,}|~{3,})(.*)$/);
79	    if (!opener) return null;
80	    const marker = opener[1];
81	    const rest = opener[2];
82	
83	    // 如果单行后续包含相同围栏符号，视为单行内闭合代码，不跨行开启围栏
84	    const inlineCloserPattern = new RegExp(`${marker[0]}{${marker.length},}`);
85	    if (inlineCloserPattern.test(rest)) {
86	      return null;
87	    }
88	
89	    return {
90	      marker,
91	      opener: Buffer.byteLength(trimmed) <= 128 ? trimmed : marker,
92	    };
93	  }
94	  const closingPattern = new RegExp(
95	    `^${current.marker[0]}{${current.marker.length},}\\s*$`,
96	  );
97	  return closingPattern.test(trimmed) ? null : current;
98	}
99	
100	/**
101	 * M2: 移除所有非 img_ 前缀的 ![alt](url) 引用，防止触发 CardKit error 200570。
102	 * 飞书卡片 markdown 元素仅认 ![desc](img_xxx)。
103	 */
104	export function stripInvalidImageKeys(text: string): string {
105	  if (!text.includes("![")) return text;
106	  return text.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, (fullMatch, _alt, target) => {
107	    const cleanTarget = target.trim().replace(/^<|>$/g, "").split(/\s+/)[0];
108	    if (cleanTarget.startsWith("img_")) return fullMatch;
109	    return "";
110	  });
111	}
112	
113	/**
114	 * Feishu Markdown Style Optimizer
115	 *
116	 * Pre-processes standard Markdown text for optimal rendering in Feishu cards:
117	 * - Heading demotion: H1 → H4, H2~H6 → H5
118	 * - Code block protection: preserved untouched with random nonce
119	 * - Strip invalid image keys from markdown text (M2)
120	 * - Table spacing: <br> padding around tables
121	 * - Consecutive heading spacing: <br> between adjacent headings
122	 * - Blank line compression: 3+ → 2
123	 */
124	export function optimizeMarkdownStyle(text: string, cardVersion = 2): string {
125	  try {
126	    return _optimizeMarkdownStyle(text, cardVersion);
127	  } catch {
128	    return text;
129	  }
130	}
131	
132	function _optimizeMarkdownStyle(text: string, cardVersion = 2): string {
133	  // 1. M6: 提取代码块并用带有一次性随机 nonce 的占位符保护
134	  const nonce = crypto.randomUUID().replace(/-/g, "").slice(0, 8);
135	  const MARK = `___TRELLIS_CB_${nonce}_`;
136	  const codeBlocks: string[] = [];
137	  let r = text.replace(/(```[\s\S]*?```|~~~[\s\S]*?~~~)/g, (m) => {
138	    return `${MARK}${codeBlocks.push(m) - 1}___`;
139	  });
140	
141	  // 2. m9: 标题降级检查在已剥离代码块的占位符文本上进行，避免代码块内的 # 误触
142	  const hasH1toH3 = /^#{1,3} /m.test(r);
143	  if (hasH1toH3) {
144	    r = r.replace(/^#{2,6} (.+)$/gm, "##### $1"); // H2~H6 → H5
145	    r = r.replace(/^# (.+)$/gm, "#### $1"); // H1 → H4
146	  }
147	
148	  // 3. M2: 在占位符保护下清理残留的非 img_ 图片语法
149	  r = stripInvalidImageKeys(r);
150	
151	  if (cardVersion >= 2) {
152	    // 4. Consecutive heading spacing
153	    r = r.replace(/^(#{4,5} .+)\n{1,2}(#{4,5} )/gm, "$1\n<br>\n$2");
154	
155	    // 5. Table spacing with <br>
156	    r = r.replace(/^([^|\n].*)\n(\|.+\|)/gm, "$1\n\n$2");
157	    r = r.replace(/\n\n((?:\|.+\|[^\S\n]*\n?)+)/g, "\n\n<br>\n\n$1");
158	    r = r.replace(/((?:^\|.+\|[^\S\n]*\n?)+)/gm, "$1\n<br>\n");
159	    r = r.replace(/^((?!#{4,5} )(?!\*\*).+)\n\n(<br>)\n\n(\|)/gm, "$1\n$2\n$3");
160	    r = r.replace(/^(\*\*.+)\n\n(<br>)\n\n(\|)/gm, "$1\n$2\n\n$3");
161	    r = r.replace(/(\|[^\n]*\n)\n(<br>\n)((?!#{4,5} )(?!\*\*))/gm, "$1$2$3");
162	
163	    // 6. Restore code blocks with <br> wrapping
164	    codeBlocks.forEach((block, i) => {
165	      r = r.replace(`${MARK}${i}___`, () => `\n<br>\n${block}\n<br>\n`);
166	    });
167	  } else {
168	    // 6. Restore code blocks without <br>
169	    codeBlocks.forEach((block, i) => {
170	      r = r.replace(`${MARK}${i}___`, () => block);
171	    });
172	  }
173	
174	  // 7. Compress excessive blank lines (3+ → 2)
175	  r = r.replace(/\n{3,}/g, "\n\n");
176	
177	  return r;
178	}
179	
180	/**
181	 * Truncate markdown text to maxLen:
182	 * - m1: 严格不超出 maxLen，先预留 note 与围栏空间；maxLen 极小时降级为省略号
183	 * - m10: sessionUrl 为空时不输出无意义链接，只输出纯文本截断提示
184	 * - 保证截断后围栏闭合
185	 */
186	export function truncateMarkdown(
187	  text: string,
188	  maxLen: number = SECTION_HARD_LIMIT,
189	  sessionUrl?: string,
190	): string {
191	  if (text.length <= maxLen) return text;
192	  if (maxLen <= 0) return "";
193	
194	  const cleanUrl = sessionUrl?.trim();
195	  const fullNote = cleanUrl
196	    ? `\n\n…（内容已截断，[详情见 Trellis 会话](${cleanUrl})）`
197	    : `\n\n…（内容已截断）`;
198	
199	  // m1: 如果 maxLen 装不下完整提示语，降级为简短省略号
200	  let note = fullNote;
201	  if (maxLen < fullNote.length + 8) {
202	    const shortNote = "…";
203	    if (maxLen < shortNote.length) {
204	      return "";
205	    }
206	    note = `\n${shortNote}`;
207	    if (maxLen < note.length) {
208	      return shortNote;
209	    }
210	  }
211	
212	  const fenceReserve = 8; // 预留闭合围栏空间（\n```）
213	  const available = maxLen - note.length - fenceReserve;
214	  if (available <= 0) {
215	    return note.trim().slice(0, maxLen);
216	  }
217	
218	  let cut = text.slice(0, available);
219	  const lastNl = cut.lastIndexOf("\n");
220	  if (lastNl > available * 0.7) {
221	    cut = cut.slice(0, lastNl);
222	  }
223	
224	  let fence: MarkdownFence | null = null;
225	  const lines = cut.split("\n");
226	  for (const line of lines) {
227	    fence = nextMarkdownFence(line, fence);
228	  }
229	
230	  if (fence) {
231	    cut += `\n${fence.marker}`;
232	  }
233	
234	  const result = `${cut}${note}`;
235	  return result.length > maxLen ? result.slice(0, maxLen) : result;
236	}
237	
238	/**
239	 * Split text into paragraphs without splitting inside code blocks.
240	 */
241	export function splitParagraphsSafely(text: string): string[] {
242	  const paragraphs: string[] = [];
243	  let curLines: string[] = [];
244	  let fence: MarkdownFence | null = null;
245	
246	  const lines = text.split("\n");
247	  for (const line of lines) {
248	    fence = nextMarkdownFence(line, fence);
249	
250	    if (!fence && !line.trim()) {
251	      if (curLines.length > 0) {
252	        paragraphs.push(curLines.join("\n").trim());
253	        curLines = [];
254	      }
255	    } else {
256	      curLines.push(line);
257	    }
258	  }
259	
260	  if (curLines.length > 0) {
261	    const remaining = curLines.join("\n").trim();
262	    if (remaining) paragraphs.push(remaining);
263	  }
264	
265	  return paragraphs.filter(Boolean);
266	}
267	
268	/**
269	 * Split body text into <= MAX_SECTIONS sections for rendering in card markdown elements.
270	 * m5: 与 happyclaw 一致，单段超限不在此处主动截断丢内容，由整卡字节预算统一管控。
271	 */
272	export function splitIntoBodySections(
273	  text: string,
274	  options?: {
275	    sessionUrl?: string;
276	    softLimit?: number;
277	    hardLimit?: number;
278	    maxSections?: number;
279	  },
280	): BodySection[] {
281	  const softLimit = options?.softLimit ?? SECTION_SOFT_LIMIT;
282	  const hardLimit = options?.hardLimit ?? SECTION_HARD_LIMIT;
283	  const maxSections = options?.maxSections ?? MAX_SECTIONS;
284	
285	  const trimmed = text.trim();
286	  if (!trimmed) return [];
287	
288	  if (trimmed.length <= softLimit) {
289	    return [{ text: trimmed }];
290	  }
291	
292	  const paragraphs = splitParagraphsSafely(trimmed);
293	
294	  const bins: string[] = [];
295	  let cur = "";
296	  for (const p of paragraphs) {
297	    if (!cur) {
298	      cur = p;
299	      continue;
300	    }
301	    const candidate = `${cur}\n\n${p}`;
302	    if (candidate.length > hardLimit) {
303	      bins.push(cur);
304	      cur = p;
305	    } else {
306	      cur = candidate;
307	    }
308	  }
309	  if (cur) bins.push(cur);
310	
311	  if (bins.length <= maxSections) {
312	    return bins.map((t) => ({ text: t }));
313	  }
314	
315	  // 溢出时：前 maxSections - 1 个保留，其余全部合并进末尾段
316	  const kept = bins.slice(0, maxSections - 1);
317	  const tail = bins.slice(maxSections - 1).join("\n\n");
318	  kept.push(tail);
319	
320	  return kept.map((t) => ({ text: t }));
321	}
322	
323	function formatImageFallback(alt: string, src: string): string {
324	  const label = alt.trim() ? `[图片] ${alt.trim()}` : `[图片]`;
325	  return `${label}: ${src}`;
326	}
327	
328	/**
329	 * 按照字节预算截断 Markdown 文本，并保证围栏闭合与截断提示附加
330	 */
331	function truncateContentToBytes(
332	  text: string,
333	  targetBytes: number,
334	  sessionUrl?: string,
335	): string {
336	  const cleanUrl = sessionUrl?.trim();
337	  const fullNote = cleanUrl
338	    ? `\n\n…（内容已截断，[详情见 Trellis 会话](${cleanUrl})）`
339	    : `\n\n…（内容已截断）`;
340	
341	  let note = fullNote;
342	  let noteBytes = Buffer.byteLength(note, "utf8");
343	  if (targetBytes < noteBytes + 16) {
344	    note = "\n\n…";
345	    noteBytes = Buffer.byteLength(note, "utf8");
346	    if (targetBytes < noteBytes) {
347	      note = "…";
348	      noteBytes = Buffer.byteLength(note, "utf8");
349	    }
350	  }
351	
352	  const fenceReserve = 16;
353	  const availableBytes = Math.max(0, targetBytes - noteBytes - fenceReserve);
354	
355	  const textBuf = Buffer.from(text, "utf8");
356	  const cutBuf = textBuf.subarray(0, availableBytes);
357	  let cut = cutBuf.toString("utf8").replace(/�+$/, "");
358	
359	  const lastNl = cut.lastIndexOf("\n");
360	  if (lastNl > cut.length * 0.7) {
361	    cut = cut.slice(0, lastNl);
362	  }
363	
364	  let fence: MarkdownFence | null = null;
365	  for (const line of cut.split("\n")) {
366	    fence = nextMarkdownFence(line, fence);
367	  }
368	  if (fence) {
369	    cut += `\n${fence.marker}`;
370	  }
371	
372	  return `${cut}${note}`;
373	}
374	
375	/**
376	 * Build a Feishu interactive card (Schema 2.0) from markdown text.
377	 */
378	export async function buildLarkCard(
379	  markdown: string,
380	  options: LarkCardOptions = {},
381	): Promise<FeishuCardV2> {
382	  const trimmed = markdown.trim();
383	
384	  // 1. M4: 计算 summary 默认值（去除 markdown 标记后的前 60 字）
385	  let cleanSummaryText: string | undefined;
386	  if (trimmed) {
387	    const clean = trimmed
388	      // 会话列表预览不渲染 <at>，原样会露出 open_id
389	      .replace(/<at\b[^>]*>([\s\S]*?)<\/at>/g, (_m, inner: string) => `@${inner}`)
390	      .replace(/!\[([^\]]*)\]\([^)]+\)/g, "")
391	      .replace(/`{1,3}[\s\S]*?`{1,3}/g, "")
392	      .replace(/[#*~_>]/g, "")
393	      .replace(/\s+/g, " ")
394	      .trim();
395	    if (clean) cleanSummaryText = clean.slice(0, 60);
396	  }
397	  const summaryText = options.summary ?? cleanSummaryText;
398	
399	  if (!trimmed) {
400	    return {
401	      schema: "2.0",
402	      config: {
403	        update_multi: true,
404	        enable_forward: true,
405	        width_mode: "fill",
406	        ...(summaryText ? { summary: { content: summaryText } } : {}),
407	      },
408	      body: {
409	        direction: "vertical",
410	        vertical_spacing: "medium",
411	        elements: [
412	          {
413	            tag: "markdown",
414	            content: EMPTY_TEXT_FALLBACK,
415	          },
416	        ],
417	      },
418	    };
419	  }
420	
421	  // 2. M6: 提取代码块，采用随机 nonce 占位符保护
422	  const cbNonce = crypto.randomUUID().replace(/-/g, "").slice(0, 8);
423	  const CB_MARK = `___TRELLIS_CB_${cbNonce}_`;
424	  const codeBlocks: string[] = [];
425	  const textWithoutCode = markdown.replace(
426	    /(```[\s\S]*?```|~~~[\s\S]*?~~~)/g,
427	    (match) => `${CB_MARK}${codeBlocks.push(match) - 1}___`,
428	  );
429	
430	  // 3. 提取非代码块区域的图片
431	  // 匹配 ![alt](url) 或 ![alt](<url>)
432	  const imgRegex = /!\[([^\]]*)\]\((?:<([^>]+)>|([^)\s]+))\)/g;
433	  type Segment =
434	    | { kind: "text"; text: string }
435	    | { kind: "img"; alt: string; src: string };
436	
437	  const segments: Segment[] = [];
438	  let lastIndex = 0;
439	  let match: RegExpExecArray | null;
440	
441	  while ((match = imgRegex.exec(textWithoutCode)) !== null) {
442	    const beforeText = textWithoutCode.slice(lastIndex, match.index);
443	    if (beforeText) {
444	      segments.push({ kind: "text", text: beforeText });
445	    }
446	    const alt = match[1] || "";
447	    const src = match[2] || match[3] || "";
448	    segments.push({ kind: "img", alt, src });
449	    lastIndex = imgRegex.lastIndex;
450	  }
451	  const remainingText = textWithoutCode.slice(lastIndex);
452	  if (remainingText) {
453	    segments.push({ kind: "text", text: remainingText });
454	  }
455	
456	  // 4. m7: 使用 Promise.allSettled 并发上传所有提取到的图片
457	  type ResolvedSegment =
458	    | { kind: "text"; text: string }
459	    | { kind: "img"; imgKey: string; alt: string };
460	
461	  const imageSegments = segments.filter((s): s is Extract<Segment, { kind: "img" }> => s.kind === "img");
462	  const uploadResults = await Promise.allSettled(
463	    imageSegments.map(async (img) => {
464	      if (options.uploadImage) {
465	        return options.uploadImage(img.src);
466	      }
467	      return img.src;
468	    }),
469	  );
470	
471	  let imageIdx = 0;
472	  const resolvedSegments: ResolvedSegment[] = [];
473	
474	  for (const segment of segments) {
475	    if (segment.kind === "text") {
476	      resolvedSegments.push(segment);
477	    } else {
478	      const res = uploadResults[imageIdx++];
479	      const key = res.status === "fulfilled" ? res.value : "";
480	      if (key && key.startsWith("img_")) {
481	        resolvedSegments.push({
482	          kind: "img",
483	          imgKey: key,
484	          alt: segment.alt,
485	        });
486	      } else {
487	        // 上传失败或非白名单，降级为文本
488	        resolvedSegments.push({
489	          kind: "text",
490	          text: formatImageFallback(segment.alt, segment.src),
491	        });
492	      }
493	    }
494	  }
495	
496	  // 5. 合并相邻的 text 片段
497	  const mergedSegments: ResolvedSegment[] = [];
498	  for (const seg of resolvedSegments) {
499	    const prev = mergedSegments[mergedSegments.length - 1];
500	    if (seg.kind === "text" && prev && prev.kind === "text") {
501	      prev.text = `${prev.text}\n\n${seg.text}`;
502	    } else {
503	      mergedSegments.push(seg);
504	    }
505	  }
506	
507	  // 6. 构造卡片 body 元素
508	  const elements: Array<Record<string, unknown>> = [];
509	
510	  for (const seg of mergedSegments) {
511	    if (seg.kind === "img") {
512	      elements.push({
513	        tag: "img",
514	        img_key: seg.imgKey,
515	        alt: {
516	          tag: "plain_text",
517	          content: seg.alt || "",
518	        },
519	        mode: "fit_horizontal",
520	        preview: true,
521	      });
522	    } else {
523	      // 还原代码块
524	      let text = seg.text;
525	      codeBlocks.forEach((block, i) => {
526	        text = text.replace(`${CB_MARK}${i}___`, () => block);
527	      });
528	
529	      // 飞书 Markdown 方言优化
530	      const optimized = optimizeMarkdownStyle(text, 2);
531	
532	      // 分段
533	      const sections = splitIntoBodySections(optimized, {
534	        sessionUrl: options.sessionUrl,
535	      });
536	
537	      for (const section of sections) {
538	        if (section.text.trim()) {
539	          let sText = section.text;
540	          let fence: MarkdownFence | null = null;
541	          for (const line of sText.split("\n")) {
542	            fence = nextMarkdownFence(line, fence);
543	          }
544	          if (fence) {
545	            sText += `\n${fence.marker}`;
546	          }
547	          elements.push({
548	            tag: "markdown",
549	            content: sText,
550	          });
551	        }
552	      }
553	    }
554	  }
555	
556	  if (elements.length === 0) {
557	    elements.push({
558	      tag: "markdown",
559	      content: EMPTY_TEXT_FALLBACK,
560	    });
561	  }
562	
563	  // 7. Header 处理（M4）
564	  const header = options.title
565	    ? {
566	        title: { tag: "plain_text" as const, content: options.title },
567	        template:
568	          options.template ??
569	          (options.status === "error"
570	            ? "red"
571	            : options.status === "warning"
572	              ? "orange"
573	              : "blue"),
574	        ...(options.subtitle
575	          ? { subtitle: { tag: "plain_text" as const, content: options.subtitle } }
576	          : {}),
577	      }
578	    : undefined;
579	
580	  const card: FeishuCardV2 = {
581	    schema: "2.0",
582	    config: {
583	      update_multi: true,
584	      enable_forward: true,
585	      width_mode: "fill",
586	      ...(summaryText ? { summary: { content: summaryText } } : {}),
587	    },
588	    ...(header ? { header } : {}),
589	    body: {
590	      direction: "vertical",
591	      vertical_spacing: "medium",
592	      elements,
593	    },
594	  };
595	
596	  // 8. M1: 整卡 UTF-8 字节预算兜底（<= CARD_MAX_BYTES 24KB）
597	  const initialTotalBytes = Buffer.byteLength(JSON.stringify(card), "utf8");
598	  if (initialTotalBytes > CARD_MAX_BYTES) {
599	    // 循环弹出无法放入 24KB 的尾部元素
600	    while (card.body.elements.length > 1) {
601	      const cardWithoutLast = {
602	        ...card,
603	        body: {
604	          ...card.body,
605	          elements: card.body.elements.slice(0, -1),
606	        },
607	      };
608	      const bytesWithoutLast = Buffer.byteLength(JSON.stringify(cardWithoutLast), "utf8");
609	      if (bytesWithoutLast >= CARD_MAX_BYTES - 256) {
610	        card.body.elements.pop();
611	        continue;
612	      }
613	      const lastElem = card.body.elements[card.body.elements.length - 1];
614	      if (lastElem.tag === "img") {
615	        card.body.elements.pop();
616	        if (Buffer.byteLength(JSON.stringify(card), "utf8") <= CARD_MAX_BYTES) break;
617	        continue;
618	      }
619	      break;
620	    }
621	
622	    // 对剩下的最后一个 markdown 元素执行精确字节截断并附带尾部链接
623	    const lastIdx = card.body.elements.length - 1;
624	    const lastElement = card.body.elements[lastIdx];
625	    if (lastElement && lastElement.tag === "markdown") {
626	      let content = String(lastElement.content ?? "");
627	      const cardWithoutLast = {
628	        ...card,
629	        body: {
630	          ...card.body,
631	          elements: card.body.elements.slice(0, -1),
632	        },
633	      };
634	      const baseBytes = Buffer.byteLength(JSON.stringify(cardWithoutLast), "utf8");
635	      let targetBytes = Math.max(40, CARD_MAX_BYTES - baseBytes - 120);
636	
637	      lastElement.content = truncateContentToBytes(content, targetBytes, options.sessionUrl);
638	
639	      while (Buffer.byteLength(JSON.stringify(card), "utf8") > CARD_MAX_BYTES && targetBytes > 30) {
640	        targetBytes -= 128;
641	        lastElement.content = truncateContentToBytes(content, targetBytes, options.sessionUrl);
642	      }
643	    }
644	  }
645	
646	  return card;
647	}
