    let sentContent = "";
    let msgType = "";
    const fakeClient = {
      im: {
        v1: {
          message: {
            create: async (params: any) => {
              msgType = params.data.msg_type;
              sentContent = params.data.content;
              return { code: 0, data: { message_id: "om_direct_card" } };
            },
          },
        },
      },
    } as any;

